// ── Extension loader ────────────────────────────────────────────────────────

/// Looks up one entry point through `eglGetProcAddress` and casts it to `T`.
pub fn getProc(comptime T: type, name: [*:0]const u8) ?T {
    const p = eglGetProcAddress(name) orelse return null;
    return @ptrCast(p);
}

/// One optional function pointer per extension entry point. A slot stays `null`
/// when the driver doesn't provide it, so check it (and the extension string from
/// `eglQueryString`) before calling. Call `load()` once EGL is usable; per the
/// spec some entry points are only valid for displays exposing the extension.
