// ── Helpers ─────────────────────────────────────────────────────────────────

/// Human-readable name for an `eglGetError()` code.
pub fn errorName(code: Int) []const u8 {
    return switch (code) {
        SUCCESS => "EGL_SUCCESS",
        NOT_INITIALIZED => "EGL_NOT_INITIALIZED",
        BAD_ACCESS => "EGL_BAD_ACCESS",
        BAD_ALLOC => "EGL_BAD_ALLOC",
        BAD_ATTRIBUTE => "EGL_BAD_ATTRIBUTE",
        BAD_CONFIG => "EGL_BAD_CONFIG",
        BAD_CONTEXT => "EGL_BAD_CONTEXT",
        BAD_CURRENT_SURFACE => "EGL_BAD_CURRENT_SURFACE",
        BAD_DISPLAY => "EGL_BAD_DISPLAY",
        BAD_MATCH => "EGL_BAD_MATCH",
        BAD_NATIVE_PIXMAP => "EGL_BAD_NATIVE_PIXMAP",
        BAD_NATIVE_WINDOW => "EGL_BAD_NATIVE_WINDOW",
        BAD_PARAMETER => "EGL_BAD_PARAMETER",
        BAD_SURFACE => "EGL_BAD_SURFACE",
        CONTEXT_LOST => "EGL_CONTEXT_LOST",
        BAD_STREAM_KHR => "EGL_BAD_STREAM_KHR",
        BAD_STATE_KHR => "EGL_BAD_STATE_KHR",
        BAD_DEVICE_EXT => "EGL_BAD_DEVICE_EXT",
        BAD_OUTPUT_LAYER_EXT => "EGL_BAD_OUTPUT_LAYER_EXT",
        BAD_OUTPUT_PORT_EXT => "EGL_BAD_OUTPUT_PORT_EXT",
        else => "unknown EGL error",
    };
}

/// Logs the pending EGL error (if any) together with what we were doing.
pub fn logError(comptime log: type, what: []const u8) void {
    const code = eglGetError();
    log.err("{s} failed: {s} (0x{x})", .{ what, errorName(code), @as(u32, @bitCast(code)) });
}

test "error names" {
    try std.testing.expectEqualStrings("EGL_BAD_ALLOC", errorName(BAD_ALLOC));
}
